package com.bank.aboveavg;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AboveAvgDemo {
    private static final Logger log = Logger.getLogger("AboveAvg");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),  // IT avg 800k → above
            new Employee("Amit", "IT", 600000),     // below
            new Employee("Priya", "Sales", 900000), // Sales avg 700k → above
            new Employee("Neha", "Sales", 500000)); // below
        AboveAverageService service = new AboveAverageService();

        log.info(() -> "Above dept average: " + service.aboveDeptAverage(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/AboveAverageService.java ───
class AboveAverageService {
    List<String> aboveDeptAverage(List<Employee> staff) {
        // pass 1: average per department
        Map<String, Double> avgByDept = staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                averagingDouble(Employee::getSalaryAsDouble)));
        // pass 2: keep employees above their own department's average
        return staff.stream()
            .filter(e -> e.getSalaryAsDouble() > avgByDept.get(e.getDepartment()))
            .map(Employee::getName)
            .toList();
    }
}
